insert into public.cards (id, owner_id, data) values
('1dab0ecd-f533-5f96-a533-f29e3f6d379c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1dab0ecd-f533-5f96-a533-f29e3f6d379c", "code": "12ER-080", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "radian", "définition"], "front": "Définition du **radian** ?", "back": "Un angle au centre mesure **1 radian** lorsqu''il intercepte un arc de longueur égale au **rayon**.\nUn tour : $360° = 2\\pi$ rad ; un demi-tour : $180° = \\pi$ rad.", "createdAt": 1794900000000, "updatedAt": 1794900000000}'::jsonb),
('491fceb9-fd34-569e-95f3-adc2ef131025', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "491fceb9-fd34-569e-95f3-adc2ef131025", "code": "12ER-081", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "longueur d''arc", "formule"], "front": "**Longueur d''un arc** de rayon $R$ et d''angle au centre $\\alpha$ ?", "back": "$\\ell = R\\,\\alpha$ avec $\\alpha$ **en radians**.\nAvec un angle de $a$ degrés : $\\ell = \\dfrac{\\pi R a}{180}$.\nEx. : $R = 4$ cm, $\\alpha = \\dfrac{\\pi}{6}$ : $\\ell = \\dfrac{2\\pi}{3}$ cm.", "createdAt": 1794900000001, "updatedAt": 1794900000001}'::jsonb),
('24e8c686-dd03-5508-8049-26c8130902d9', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "24e8c686-dd03-5508-8049-26c8130902d9", "code": "12ER-082", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "longueur d''arc", "piège"], "front": "**Piège** : arc de rayon 2 cm et d''angle $60°$. Pourquoi pas $\\ell = 2 \\times 60$ ?", "back": "Dans $\\ell = R\\alpha$, l''angle doit être **en radians** : $60° = \\dfrac{\\pi}{3}$ rad.\n$\\ell = 2 \\times \\dfrac{\\pi}{3} = \\dfrac{2\\pi}{3} \\approx 2{,}09$ cm.", "createdAt": 1794900000002, "updatedAt": 1794900000002}'::jsonb),
('4eca6687-abf4-5927-915e-9e266d87d51a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4eca6687-abf4-5927-915e-9e266d87d51a", "code": "12ER-083", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "longueur d''arc", "exemple"], "front": "Sur un cercle de rayon 3, un arc mesure $\\dfrac{\\pi}{4}$. Angle au centre en degrés ?", "back": "On écrit la relation : $\\dfrac{\\pi}{4} = 3\\,\\alpha$, donc $\\alpha = \\dfrac{\\pi}{12}$ rad.\n$\\dfrac{\\pi}{12} \\times \\dfrac{180}{\\pi} = 15°$", "createdAt": 1794900000003, "updatedAt": 1794900000003}'::jsonb),
('2edf27d9-84a8-5925-8d65-bdcd75b64a3a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2edf27d9-84a8-5925-8d65-bdcd75b64a3a", "code": "12ER-084", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "radian", "conversion"], "front": "Correspondances à connaître : $30°$, $45°$, $60°$, $90°$, $180°$, $360°$ en radians ?", "back": "$30° = \\dfrac{\\pi}{6}$ ; $45° = \\dfrac{\\pi}{4}$ ; $60° = \\dfrac{\\pi}{3}$ ; $90° = \\dfrac{\\pi}{2}$ ; $180° = \\pi$ ; $360° = 2\\pi$\nRadians vers degrés : $\\times \\dfrac{180}{\\pi}$. Ex. : $\\dfrac{5\\pi}{6}$ rad $= 150°$.", "createdAt": 1794900000004, "updatedAt": 1794900000004}'::jsonb),
('d5817350-e10a-55bd-9d73-c9a0d0cfac66', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d5817350-e10a-55bd-9d73-c9a0d0cfac66", "code": "12ER-085", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "cercle trigonométrique", "point image"], "front": "Enroulement : comment placer le point image d''un réel $x$ **négatif** ?", "back": "On part de $I(1\\,;\\,0)$ et on parcourt la longueur $-x$ dans le sens **indirect** (celui des aiguilles d''une montre).\nLe signe de $x$ indique le **sens**, ce n''est pas une longueur négative.", "createdAt": 1794900000005, "updatedAt": 1794900000005}'::jsonb),
('84b53346-e03c-5393-8937-e6c8af69e07d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "84b53346-e03c-5393-8937-e6c8af69e07d", "code": "12ER-086", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "point image", "exemple"], "front": "Points images de $0$, $\\dfrac{\\pi}{2}$, $\\pi$, $\\dfrac{3\\pi}{2}$ et $-\\dfrac{\\pi}{2}$ ?", "back": "$0$ : $I(1\\,;\\,0)$ ; $\\dfrac{\\pi}{2}$ : $J(0\\,;\\,1)$ ; $\\pi$ : $L(-1\\,;\\,0)$\n$\\dfrac{3\\pi}{2}$ et $-\\dfrac{\\pi}{2}$ : le même point $K(0\\,;\\,-1)$", "createdAt": 1794900000006, "updatedAt": 1794900000006}'::jsonb),
('b8f19f09-2eb4-5f5c-998d-beba83bb1b11', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b8f19f09-2eb4-5f5c-998d-beba83bb1b11", "code": "12ER-087", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "point image", "propriété"], "front": "Quand deux réels $x$ et $x''$ ont-ils le **même point image** ?", "back": "Si et seulement si $x - x'' = 2k\\pi$, avec $k$ entier relatif : la différence est un nombre entier de tours.\nEx. : $\\dfrac{13\\pi}{4} - \\left(-\\dfrac{3\\pi}{4}\\right) = 4\\pi$ : même point.", "createdAt": 1794900000007, "updatedAt": 1794900000007}'::jsonb),
('37543b16-adc1-5704-ac3d-63dbf5957386', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "37543b16-adc1-5704-ac3d-63dbf5957386", "code": "12ER-088", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "point image", "méthode"], "front": "Méthode en 3 étapes : placer $\\dfrac{19\\pi}{6}$ sur le cercle ?", "back": "1. Sens : positif, donc sens direct.\n2. Retirer des tours : $\\dfrac{19\\pi}{6} = 2\\pi + \\dfrac{7\\pi}{6}$.\n3. Fraction de tour : $\\dfrac{7\\pi}{6} = \\pi + \\dfrac{\\pi}{6}$, soit $210°$ à partir de $I$.", "createdAt": 1794900000008, "updatedAt": 1794900000008}'::jsonb),
('332b05b3-fce2-5b4f-875c-1f31b44ff838', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "332b05b3-fce2-5b4f-875c-1f31b44ff838", "code": "12ER-089", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "cosinus", "piège"], "front": "**Piège** : $M$ est le point image de $x$. Son abscisse vaut-elle $x$ ?", "back": "**Non** : $x$ indique le parcours sur le cercle.\nL''abscisse de $M$ est $\\cos x$ et son ordonnée $\\sin x$ : $M(\\cos x\\,;\\,\\sin x)$.", "createdAt": 1794900000009, "updatedAt": 1794900000009}'::jsonb),
('1deab37c-036a-516a-b07c-52b935efaaf2', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1deab37c-036a-516a-b07c-52b935efaaf2", "code": "12ER-090", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "cosinus", "sinus"], "front": "Pour $0 \\lt x \\lt \\dfrac{\\pi}{2}$, lien entre le cercle et le **triangle rectangle** $OHM$ ?", "back": "$OHM$ est rectangle en $H$ et $OM = 1$ : $\\cos x = \\dfrac{OH}{OM} = OH$ et $\\sin x = \\dfrac{HM}{OM} = HM$.\nLes définitions sur le cercle prolongent celles du collège.", "createdAt": 1794900000010, "updatedAt": 1794900000010}'::jsonb),
('ef7579a9-5884-5997-b089-8fc1a47a2a22', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ef7579a9-5884-5997-b089-8fc1a47a2a22", "code": "12ER-091", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "valeurs remarquables", "démonstration"], "front": "Retrouver $\\cos \\dfrac{\\pi}{4}$ et $\\sin \\dfrac{\\pi}{4}$ sans les apprendre ?", "back": "Triangle rectangle **isocèle** de côtés $a$ : hypoténuse $a\\sqrt{2}$ (Pythagore).\n$\\cos \\dfrac{\\pi}{4} = \\sin \\dfrac{\\pi}{4} = \\dfrac{a}{a\\sqrt{2}} = \\dfrac{\\sqrt{2}}{2}$", "createdAt": 1794900000011, "updatedAt": 1794900000011}'::jsonb),
('6c7e9fbb-bef0-5361-b430-0174c16eb0ba', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "6c7e9fbb-bef0-5361-b430-0174c16eb0ba", "code": "12ER-092", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "valeurs remarquables", "démonstration"], "front": "Retrouver les valeurs remarquables de $\\dfrac{\\pi}{3}$ et $\\dfrac{\\pi}{6}$ ?", "back": "Triangle **équilatéral** de côté $a$ : une hauteur coupe la base en $\\dfrac{a}{2}$ et mesure $\\dfrac{a\\sqrt{3}}{2}$.\n$\\cos \\dfrac{\\pi}{3} = \\sin \\dfrac{\\pi}{6} = \\dfrac{1}{2}$ ; $\\sin \\dfrac{\\pi}{3} = \\cos \\dfrac{\\pi}{6} = \\dfrac{\\sqrt{3}}{2}$", "createdAt": 1794900000012, "updatedAt": 1794900000012}'::jsonb),
('2a92e446-c951-5968-af57-2a61acc05991', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2a92e446-c951-5968-af57-2a61acc05991", "code": "12ER-093", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "sinus", "exemple"], "front": "$0 \\lt x \\lt \\dfrac{\\pi}{2}$ et $\\cos x = \\dfrac{3}{5}$ : calculer $\\sin x$.", "back": "$\\sin^2 x = 1 - \\cos^2 x = 1 - \\dfrac{9}{25} = \\dfrac{16}{25}$\nDans ce quart de cercle, $\\sin x \\gt 0$, donc $\\sin x = \\dfrac{4}{5}$.", "createdAt": 1794900000013, "updatedAt": 1794900000013}'::jsonb),
('fb2e0f6e-3c44-59c1-9ff1-92267a20bf45', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "fb2e0f6e-3c44-59c1-9ff1-92267a20bf45", "code": "12ER-094", "origin": "ER", "subject": "Mathématiques", "level": "1re", "theme": "Fonctions", "introUnitId": "76a05229-d5eb-5b95-b730-fdc0e6460b8c", "tags": ["1re", "Fonctions", "Fonctions trigonométriques", "calculatrice", "piège"], "front": "**Calculatrice** : que vérifier avant un calcul de $\\cos$ ou $\\sin$ en radians ?", "back": "Le mode **RAD** (et non DEG).\nDonner les **valeurs exactes** (avec $\\pi$ et les racines) quand elles sont demandées.", "createdAt": 1794900000014, "updatedAt": 1794900000014}'::jsonb);
