begin;
update public.unit_cards uc set data = uc.data - 'suspended' from public.cards c where c.id = uc.card_id and uc.unit_id = 'ccf4fc8d-ff10-46d9-a3bf-ae094f0c9ea6' and c.data->>'code' in ('34ER-010', '34ER-011', '34ER-012', '24ER-002', '24ER-003');
update public.tutoring_sessions set data = jsonb_set(data, '{cardIds}', data->'cardIds' || (select jsonb_agg(id::text order by data->>'code') from public.cards where data->>'code' in ('12ER-072', '12ER-073', '12ER-074', '12ER-075', '34ER-010', '34ER-011', '34ER-012', '24ER-002', '24ER-003') and not deleted)) where id = '0fd876b3-34ea-53a8-8c6e-ae6bd6083069';
commit;
select (select jsonb_array_length(data->'cardIds') from public.tutoring_sessions where id = '0fd876b3-34ea-53a8-8c6e-ae6bd6083069') as flashcards_seance, (select count(*) from public.unit_cards where unit_id = '266ea801-1b25-5eab-ac40-e8d62e870979' and not deleted) as cartes_1241, (select string_agg(c.data->>'code', ',' order by c.data->>'code') from public.unit_cards uc join public.cards c on c.id = uc.card_id where uc.unit_id = 'ccf4fc8d-ff10-46d9-a3bf-ae094f0c9ea6' and coalesce((uc.data->>'suspended')::boolean, false) = false) as actives_1240;
